// Inspect Media page nodes and key text nodes in order to reuse components
const out = [];

function fmtColor(c) {
  if (!c) return null;
  return '#' + [Math.round(c.r*255), Math.round(c.g*255), Math.round(c.b*255)].map(v => v.toString(16).padStart(2,'0')).join('');
}

function dump(node, depth) {
  const pad = '  '.repeat(depth);
  let info = pad + node.type + ' "' + node.name + '" id=' + node.id;
  if ('x' in node) info += ' x=' + Math.round(node.x) + ' y=' + Math.round(node.y) + ' w=' + Math.round(node.width) + ' h=' + Math.round(node.height);
  if (node.type === 'TEXT') {
    const f = node.fontName;
    info += ' fontSize=' + node.fontSize + ' font=' + (f ? (f.family + '/' + f.style) : '?') + ' characters=' + JSON.stringify(node.characters).slice(0,80);
    info += ' fills=' + JSON.stringify(node.fills ? node.fills.map(fl => ({type: fl.type, color: fmtColor(fl.color)})) : null);
  }
  if (node.type === 'COMPONENT' || node.type === 'COMPONENT_SET') {
    info += ' key=' + node.key;
  }
  if ('fills' in node && node.fills) {
    const imgs = node.fills.filter(f => f.type === 'IMAGE');
    if (imgs.length) info += ' IMAGEFILLS=' + imgs.map(f => f.imageHash ? f.imageHash.slice(0,12) : '?').join(',');
  }
  out.push(info);
  if ('children' in node) {
    node.children.forEach(c => dump(c, depth + 1));
  }
}

const pages = figma.root.children.map(p => p.name + ' [' + p.id + ']');
out.push('PAGES: ' + pages.join(' | '));

const mediaPage = figma.root.children.find(p => p.name.indexOf('Media') >= 0);
if (mediaPage) {
  out.push('=== MEDIA PAGE ===');
  mediaPage.children.forEach(c => dump(c, 0));
}

// Start Here text nodes for exact copy
const startPage = figma.root.children.find(p => p.name.indexOf('Start') >= 0);
if (startPage) {
  out.push('=== START HEADER TEXTS ===');
  const header = startPage.findOne(n => n.type === 'TEXT' && n.name === 'Deniz Arslan — 3D artist portfolio');
  if (header) { out.push('TITLE font=' + JSON.stringify(header.fontName) + ' size=' + header.fontSize + ' chars=' + JSON.stringify(header.characters)); }
  const sub = startPage.findOne(n => n.type === 'TEXT' && n.characters && n.characters.indexOf('two-page personal portfolio') >= 0);
  if (sub) { out.push('SUB font=' + JSON.stringify(sub.fontName) + ' size=' + sub.fontSize + ' chars=' + JSON.stringify(sub.characters)); }
}

figma.notify('Inspection done');
console.log(out.join('\n'));

(async () => {
  // Switch to the Workspace page
  const ws = figma.root.children.find(p => p.name === '03 · Workspace');
  if (!ws) throw new Error('Workspace page not found');
  await figma.setCurrentPageAsync(ws);

  const DM = {
    Regular: { family: 'DM Sans', style: 'Regular' },
    Medium: { family: 'DM Sans', style: 'Medium' },
    Bold: { family: 'DM Sans', style: 'Bold' },
  };
  for (const k of Object.keys(DM)) {
    try { await figma.loadFontAsync(DM[k]); }
    catch (e) { throw new Error('loadFont ' + k + ' failed: ' + e.message); }
  }

  const hex = (h) => {
    const v = h.replace('#', '');
    return { r: parseInt(v.slice(0,2),16)/255, g: parseInt(v.slice(2,4),16)/255, b: parseInt(v.slice(4,6),16)/255 };
  };

  // ---- Paint styles ----
  const paintDefs = {
    'DA/Bg': '#FFFFFF',
    'DA/Ink': '#181717',
    'DA/Accent': '#2429AF',
    'DA/SecText': '#606060',
    'DA/Divider': '#E7E7E8',
    'DA/PlaceholderFill': '#F4F4F5',
    'DA/PlaceholderText': '#B4B4B8',
  };
  for (const [name, h] of Object.entries(paintDefs)) {
    let s = figma.getLocalPaintStyles().find(x => x.name === name);
    if (!s) s = figma.createPaintStyle();
    s.name = name;
    s.paints = [{ type: 'SOLID', color: hex(h) }];
  }

  // ---- Text styles (no color baked in; colors applied per node) ----
  const ts = (name, font, size, lh, decoration) => {
    let s = figma.getLocalTextStyles().find(x => x.name === name);
    if (!s) s = figma.createTextStyle();
    s.name = name;
    s.fontName = font;
    s.fontSize = size;
    s.lineHeight = { value: lh, unit: 'PIXELS' };
    s.letterSpacing = { value: 0, unit: 'PIXELS' };
    if (decoration) s.textDecoration = decoration;
    return s;
  };

  ts('DA/Display XL', DM.Bold, 96, 104);
  ts('DA/Display L', DM.Bold, 72, 84);
  ts('DA/H2', DM.Bold, 44, 54);
  ts('DA/H3', DM.Bold, 32, 40);
  ts('DA/H4', DM.Medium, 22, 30);
  ts('DA/Lead', DM.Regular, 20, 30);
  ts('DA/Body', DM.Regular, 18, 28);
  ts('DA/Meta', DM.Regular, 14, 22);
  ts('DA/Nav', DM.Medium, 17, 24);
  ts('DA/NavCurrent', DM.Medium, 17, 24, 'UNDERLINE');
  ts('DA/Link', DM.Medium, 16, 24);
  ts('DA/Status', DM.Medium, 14, 20);
  ts('DA/PlaceholderLabel', DM.Regular, 13, 18);
  ts('DA/Num', DM.Medium, 18, 24);
  ts('DA/Footer', DM.Regular, 16, 24);

  figma.notify('Fonts + design tokens ready');
})().catch(e => { figma.notify('Error: ' + e.message, { error: true }); throw e; });

