  if (photo) {
    let imgInfo = [];
    function scanImg(node, path) {
      if ('fills' in node && node.fills) {
        node.fills.forEach((f, i) => {
          if (f.type === 'IMAGE') imgInfo.push(path + ' fills[' + i + '] imageHash=' + String(f.imageHash || '').slice(0, 16) + ' visible=' + f.visible);
