          else imgInfo.push(path + ' fills[' + i + '] ' + f.type);
        });
      }
      if (node.type === 'RECTANGLE' || node.type === 'ELLIPSE' || node.type === 'VECTOR' || node.type === 'POLYGON' || node.type === 'STAR' || node.type === 'FRAME' || node.type === 'GROUP' || node.type === 'COMPONENT' || node.type === 'INSTANCE' || node.type === 'LINE') {
        if ('children' in node && node.children) node.children.forEach(c => scanImg(c, path + '/' + c.name + ':' + c.type));
      }
    }
    scanImg(photo, photo.name);
    out.push('PHOTO scan: ' + JSON.stringify(imgInfo.slice(0, 30)));
    out.push('PHOTO children: ' + JSON.stringify(photo.children.map(c => c.type + ':' + c.name)));
